$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert"),crypto=require("crypto");
const paths={
  unaliased:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json",
  aliased:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json",
  lookup:"references/instruction-wrapper-key-aliases.json",
  task:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json"
};
const read=p=>JSON.parse(fs.readFileSync(p,"utf8"));
const write=(p,v,compact=false)=>fs.writeFileSync(p,JSON.stringify(v,null,compact?0:2)+"\n");
const orig=read(paths.unaliased),oldCopy=read(paths.aliased),map=read(paths.lookup),task=read(paths.task);
assert(Array.isArray(orig)&&orig.length===3&&typeof orig[0]==="object"&&!Array.isArray(orig[0]));
assert(oldCopy[0].alias_lookup_path===paths.lookup);
assert(!Object.hasOwn(orig[0],"github_repository_documentation_preflight"));
assert(task.status==="pending_revision");
const newKey="github_repository_documentation_preflight";
const newInstruction="Before beginning operations in any GitHub repository, retrieve and review its repository README and agent guidance documents, using either the Markdown or JSON form of each (Readme.md or Readme.json, and AGENTS.md or AGENTS.json). Complete this document review before proceeding with repository work.";
const updated=structuredClone(orig);
updated[0][newKey]=newInstruction;
assert.deepStrictEqual(updated[1],orig[1]);
assert.deepStrictEqual(updated[2],orig[2]);
const oldAliases=map.alias_to_key;
assert(oldAliases.g==="governing_references"&&!Object.hasOwn(oldAliases,"ga"));
const revisedAliases={...oldAliases,ga:newKey};
const k2a=new Map(Object.entries(revisedAliases).map(([a,k])=>[k,a]));
function encode(v){if(Array.isArray(v))return v.map(encode);if(!v||typeof v!=="object")return v;const o={};for(const [k,x]of Object.entries(v)){assert(k2a.has(k),"Missing alias "+k);o[k2a.get(k)]=encode(x);}return o;}
function decode(v){if(Array.isArray(v))return v.map(decode);if(!v||typeof v!=="object")return v;const o={};for(const [k,x]of Object.entries(v)){const named=k==="alias_lookup_path"?k:revisedAliases[k];assert(named,"No mapping for "+k);o[named]=decode(x);}return o;}
const encoded=encode(updated);encoded[0].alias_lookup_path=paths.lookup;
const back=decode(encoded);delete back[0].alias_lookup_path;assert.deepStrictEqual(back,updated);
const encountered=new Set();function countKeys(v){if(Array.isArray(v))return v.forEach(countKeys);if(!v||typeof v!=="object")return;for(const [key,val]of Object.entries(v)){encountered.add(key);countKeys(val);}}countKeys(updated);
assert(encountered.size===Object.keys(revisedAliases).length);
map.alias_to_key=revisedAliases;
map.original_key_count=encountered.size;
map.total_key_count_including_lookup=encountered.size;
map.aliases_with_one_character=Object.keys(revisedAliases).filter(k=>k.length===1).length;
map.aliases_with_two_characters=Object.keys(revisedAliases).filter(k=>k.length===2).length;
map.source_template_sha256=crypto.createHash("sha256").update(JSON.stringify(updated,null,2)+"\n").digest("hex");
task.task.amendments.push({
  purpose:"Add an explicit repository-documentation preflight instruction to the outer index-zero explainer.",
  user_instruction_summary:"Before carrying out operations in a GitHub repository, fetch and read its README and AGENTS documents, using Markdown or JSON variants. Express the instruction equivalently rather than verbatim.",
  implementation:"The outer index-zero explainer has a github_repository_documentation_preflight instruction. Update the aliased copy and the alias reference without modifying the complete standalone scope and analytics rules.",
  status:"pending_user_review"
});
write(paths.unaliased,updated);
write(paths.aliased,encoded,true);
write(paths.lookup,map);
write(paths.task,task);
assert.deepStrictEqual(read(paths.unaliased)[1],orig[1]);
assert.deepStrictEqual(read(paths.unaliased)[2],orig[2]);
const saved=decode(read(paths.aliased));delete saved[0].alias_lookup_path;assert.deepStrictEqual(saved,read(paths.unaliased));
assert.strictEqual(read(paths.unaliased)[0][newKey],newInstruction);
assert(read(paths.task).status==="pending_revision");
console.log("PUBLISHED_INSTRUCTION_KEY",newKey);
console.log("INSTRUCTION",newInstruction);
console.log("INDEX_ZERO_KEYS",JSON.stringify(Object.keys(updated[0])));
console.log("ALIAS_FOR_NEW_KEY",k2a.get(newKey));
console.log("PRESERVED_RULES",true);
console.log("ROUNDTRIP_VALID",true);
console.log("UNALIASED_CHARACTERS",fs.readFileSync(paths.unaliased,"utf8").length);
console.log("ALIASED_CHARACTERS",fs.readFileSync(paths.aliased,"utf8").length);
NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json' 'references/instruction-wrapper-key-aliases.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json'
git diff --cached --check
git commit -m 'Require README and AGENTS preflight before GitHub repository operations'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
git show --stat --oneline HEAD
